import raw from "../../data/subway-stations.json";

/** Typed view over data/subway-stations.json (generated by scripts/build-stations.ts). */
export type SubwayStop = { id: string; name: string; north: string; south: string };
export type SubwayComplex = {
  id: string;
  name: string;
  borough: string;
  routes: string[];
  stops: SubwayStop[];
};
export type SubwayRoute = { label: string; color: string };

export const SUBWAY_COMPLEXES: SubwayComplex[] = raw.complexes;
export const SUBWAY_ROUTES: Record<string, SubwayRoute> = raw.routes;

const complexById = new Map(SUBWAY_COMPLEXES.map((c) => [c.id, c]));
const stopById = new Map(SUBWAY_COMPLEXES.flatMap((c) => c.stops.map((s) => [s.id, s] as const)));

export function getComplex(id: string): SubwayComplex | undefined {
  return complexById.get(id);
}

/** Looks up a parent stop from a realtime stop id such as "127N" or "A27". */
export function getStop(realtimeStopId: string): SubwayStop | undefined {
  return stopById.get(realtimeStopId.replace(/[NS]$/, ""));
}
